#define pi acos(-1.)
#define sq sqrt(3.) / 3.

float rect(vec2 p, float ds){
    p.x += ds;
    p = abs(p) - vec2(3, 1) / 100.;
    return max(p.x, p.y);
}

void grid(vec2 u, out vec2 p) {
    float v;
    vec2 q, m;

    q = u - vec2(0, -sq);
    p.y = dot(q, q); 

    m = u - vec2(-1, sq) / 2.;
    v = dot(m, m); if(v < p.y) {p.y = v; q = m;}

    m = u - vec2(1, sq) / 2.;
    v = dot(m, m); if(v < p.y) {p.y = v; q = m;}

    p = q;
}

void hex(vec2 u, out vec2 p, out bool checker){
    vec2 q, id, A, B;

    q = u;

    vec2 H = vec2(1, 2. * sq);

    q.x += fract(q.y * sq) > .5 ? .0 : .5;
    q    = (mod(q * H, 1.) - .5) / H;

    id = u - q;
    float d = sin(dot(id, vec2(1))) + id.x * .1;

    grid(q, A);
    grid(q * vec2(1, -1), B);

    checker = fract(d) > .5;

    p = A;
    if(checker) p = B;
}

void mainImage(out vec4 o, vec2 u) {
    vec2 r = iResolution.xy, q;
    u = 1.6 * (u + u - r) / r.y 
      +  4. * tanh(vec2(cos(iTime * .3), sin(iTime * .2)) * 5.);

    vec2 p;
    bool checker;
    hex(u, p, checker);

    float d = atan(p.y, p.x) + iTime;
          d = (mod(d * 12., 2. * pi) - pi) / 12.;

    q = cos(d + vec2(0, 3) * pi / 2.)
         * length(p) - vec2(.288, 0);


    // draw
    vec4 c = vec4(2, 3, 4, 0) / 6.; 

    vec4 bg = checker? c.zyxw : c;

    float pins = rect(q, checker? -.05 : .05),
          dots = length(q) - .03,
          fosfolipidios = min(pins, dots);

    o = max(bg, smoothstep(.03, .0, fosfolipidios));
}
